rule "Evaluation: Self Monitoring Logs - Parser NGINX"
when
    grok("^%{IPV4}", to_string($message.message)).matches == true

then
    let message = multi_grok(
        value: to_string($message.message), 
        patterns: [
            "^%{IPV4:source_ip}[\\s\\-]+\\[%{HTTPDATE:event_created}\\]%{GREEDYDATA:todo}$"
        ],
        only_named_captures: true
    );

    set_fields(message);
    set_field("event_created", to_date(flex_parse_date(to_string($message.event_created)))); 
    set_field("source_ip", to_ip($message.source_ip));
    set_field("application_name", "nginx");

end

rule "Evaluation: Self Monitoring Logs - Parser MULTILINE"
when 
    contains(to_string($message.filebeat_log_flags), "multiline")

then
    let stacklog = to_map(parse_json(to_string($message.message)));

    set_field("full_message", to_string($message.message));
    set_field("event_collected", to_date(flex_parse_date(to_string(stacklog.time))));
    set_fields(stacklog);

    rename_fields(
        fields: {
            log:                        "message"
            filebeat_log_file_path:     "event_log_path"
        }

    );

    remove_multiple_fields(
        names: ["stream","time"],
        pattern: "filebeat_.*"
    );

    set_field("log_type", "stacktrace");

end

rule "Evaluation: Self Monitoring Logs - Parser SINGLELINE"
when 
    NOT starts_with(to_string($message.filebeat_log_file_path), "/var/log/syslog")
    AND NOT contains(to_string($message.filebeat_log_flags), "multiline")

then
    let stacklog = to_map(parse_json(to_string($message.message)));

    set_field("full_message", to_string($message.message));
    set_field("event_collected", to_date(flex_parse_date(to_string(stacklog.time))));
    set_fields(stacklog);

    rename_fields(
        fields: {
            log:                        "message"
            filebeat_log_file_path:     "event_log_path"
        }

    );

    remove_multiple_fields(
        names: ["stream","time"],
        pattern: "filebeat_.*"
    );

end

rule "Evaluation: Self Monitoring Logs - Parser GRAYLOG"
when
    grok("^%{TIMESTAMP_ISO8601}", to_string($message.message)).matches == true

then
    let message = multi_grok(
        value: to_string($message.message), 
        patterns: [
            "^%{TIMESTAMP_ISO8601:event_created}%{SPACE}%{LOGLEVEL:event_severity}\\:%{SPACE}%{NOTSPACE:application_component}%{SPACE}\\-%{SPACE}%{DATA:message}$"
        ],
        only_named_captures: true
    );

    set_field("event_collected", to_date(flex_parse_date(to_string(stacklog.time))));
    set_field("full_message", to_string(stacklog.log));
    set_fields(message);
    set_field("application_name", "graylog");

end
